{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Sampled training separation is weakest for CDs_and_Vinyl: negatives outrank positives in 27.87% of pairs, versus 17.81% for Electronics and approximately 12–13% for the other datasets. Every dataset has a negative 10th-percentile margin.",
    "Item embeddings show substantial directional alignment in Industrial_and_Scientific and Electronics, with geometry scores of 0.8526 and 0.8387; CDs_and_Vinyl is closer to zero mean cosine at 0.5307. All catalog embeddings were usable, and margin measurements excluded no invalid negatives or nonfinite scores."
  ],
  "key_implications": [
    "Positive mean training margins coexist with a meaningful fraction of incorrectly ordered sampled pairs, especially for CDs_and_Vinyl.",
    "Directional alignment alone does not establish representation failure, and near-zero mean cosine does not guarantee strong sampled separation.",
    "These measurements cannot establish validation HR@10, recommendation diversity, simulator traits, or pooling-residual correctness; category annotations are unavailable with zero annotated support."
  ],
  "evidence": {
    "headline_metrics": {
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.2787,
      "CDs_and_Vinyl:pos_neg_margin_p10": -0.8953,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.1781,
      "Industrial_and_Scientific:embedding_collapse_score": 0.8526,
      "CDs_and_Vinyl:embedding_collapse_score": 0.5307
    },
    "brief_metric_read": {
      "pos_neg_margin_support": "Measured positions: Movies 11,841; Industrial 10,584; Electronics 10,565; CDs 15,290; zero invalid negatives or nonfinite positions.",
      "embedding_support": "2,048 items and 2,096,128 pairs sampled per dataset; zero excluded catalog embeddings.",
      "embedding_collapse_score": "Mapped mean cosine measures directional alignment, not recommendation diversity."
    }
  }
}
